use entmoot_contracts::*;
use std::mem::size_of;

fn main() {
    let mut sizes = std::collections::BTreeMap::new();
    macro_rules! record {
        ($($ty:ty),+ $(,)?) => { $(sizes.insert(stringify!($ty), size_of::<$ty>());)+ };
    }
    record!(Address, SourceSnapshot, Scope, ProducerRef, Provenance, Proposition,
        RelationEdge, RelationClaim, RelationClaimValue, AssessmentObservation,
        UnresolvedRelation, ResolvedIdentityRecord, ResolverObservation, ResolverTarget,
        ArtifactManifest, KnowledgeRecordRef, ArtifactInputReceipt,
        ProviderCallableRef, Option<ProviderCallableRef>, ResolverDeclaration,
        Option<ResolverDeclaration>, SubjectId, DerivationRecord, Option<DerivationRecord>,
        ArtifactRevalidationReceipt, RevalidationUnitReceipt,
        OperationSpec, OperationRecord,
        entmoot_contracts::query::QueryResult,
        entmoot_contracts::query::QueryPayload,
        entmoot_contracts::query::CompactItem,
        entmoot_topology::TopologyNode, entmoot_topology::StructuralEdge);
    println!("{}", serde_json::to_string_pretty(&sizes).unwrap());
}
